#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <openssl/evp.h>
#include <openssl/rand.h>

#define MAX_CONNECTIONS 64
#define HEADER_SIZE 8
#define AES_BLOCK_SIZE 16
#define IV_SIZE 16
#define KEY_SIZE 32

typedef struct {
    uint16_t version;
    uint16_t flags;
    uint16_t num_chunks;
    uint16_t chunk_size;
} __attribute__((packed)) proxy_header_t;

typedef struct {
    unsigned char key[KEY_SIZE];
    unsigned char iv[IV_SIZE];
    int client_fd;
    int backend_fd;
} session_t;

static session_t sessions[MAX_CONNECTIONS];

static size_t compute_storage_size(const proxy_header_t *hdr) {
    /* Each chunk is encrypted with AES-256-CBC, which pads to block boundary.
     * Storage needed = num_chunks * padded_chunk_size + IV per chunk.
     * padded_chunk_size = ((chunk_size / AES_BLOCK_SIZE) + 1) * AES_BLOCK_SIZE
     */
    uint32_t padded = ((uint32_t)(hdr->chunk_size / AES_BLOCK_SIZE) + 1) * AES_BLOCK_SIZE;
    uint32_t per_chunk = padded + IV_SIZE;
    /* Total storage: header + all encrypted chunks */
    size_t total = HEADER_SIZE + (uint32_t)(hdr->num_chunks) * per_chunk;
    return total;
}

static int encrypt_chunk(const unsigned char *plaintext, uint16_t plain_len,
                         const unsigned char *key, unsigned char *out,
                         size_t out_capacity) {
    EVP_CIPHER_CTX *ctx;
    int len, ciphertext_len;
    unsigned char *iv = out;

    if (out_capacity < IV_SIZE)
        return -1;

    RAND_bytes(iv, IV_SIZE);

    ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return -1;

    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    if (EVP_EncryptUpdate(ctx, out + IV_SIZE, &len, plaintext, plain_len) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    ciphertext_len = len;

    if (EVP_EncryptFinal_ex(ctx, out + IV_SIZE + len, &len) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    ciphertext_len += len;

    EVP_CIPHER_CTX_free(ctx);
    return IV_SIZE + ciphertext_len;
}

static int process_proxy_request(int session_idx, const unsigned char *data, size_t data_len) {
    if (data_len < HEADER_SIZE)
        return -1;

    proxy_header_t hdr;
    memcpy(&hdr, data, HEADER_SIZE);

    /* Version check */
    if (hdr.version != 0x0102)
        return -1;

    /* Sanity: individual chunk_size must be reasonable */
    if (hdr.chunk_size == 0 || hdr.chunk_size > 4096)
        return -1;

    /* Sanity: num_chunks must be reasonable */
    if (hdr.num_chunks == 0 || hdr.num_chunks > 1024)
        return -1;

    /* Verify we have enough input data */
    size_t expected_input = HEADER_SIZE + (size_t)hdr.num_chunks * hdr.chunk_size;
    if (data_len < expected_input)
        return -1;

    /* Compute encrypted storage buffer size */
    size_t storage_size = compute_storage_size(&hdr);

    /* Allocate storage for encrypted proxy cache */
    unsigned char *storage = (unsigned char *)malloc(storage_size);
    if (!storage)
        return -1;

    /* Copy header to storage */
    memcpy(storage, &hdr, HEADER_SIZE);

    /* Encrypt each chunk and store */
    size_t offset = HEADER_SIZE;
    const unsigned char *chunk_ptr = data + HEADER_SIZE;
    session_t *sess = &sessions[session_idx];

    for (uint16_t i = 0; i < hdr.num_chunks; i++) {
        size_t remaining = storage_size - offset;
        int written = encrypt_chunk(chunk_ptr, hdr.chunk_size,
                                    sess->key, storage + offset, remaining);
        if (written < 0) {
            free(storage);
            return -1;
        }
        offset += written;
        chunk_ptr += hdr.chunk_size;
    }

    /* Forward encrypted data to backend */
    ssize_t sent = write(sess->backend_fd, storage, offset);
    free(storage);

    return (sent > 0) ? 0 : -1;
}

static int handle_client(int client_fd, int session_idx) {
    unsigned char buffer[65536];
    ssize_t n = read(client_fd, buffer, sizeof(buffer));
    if (n <= 0)
        return -1;

    return process_proxy_request(session_idx, buffer, (size_t)n);
}

int main(int argc, char *argv[]) {
    int server_fd;
    struct sockaddr_in addr;

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) return 1;

    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons(8443);

    if (bind(server_fd, (struct sockaddr *)&addr, sizeof(addr)) < 0)
        return 1;

    listen(server_fd, MAX_CONNECTIONS);

    /* Initialize session keys */
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        RAND_bytes(sessions[i].key, KEY_SIZE);
    }

    printf("Proxy listening on port 8443\n");

    int session_idx = 0;
    while (1) {
        int client_fd = accept(server_fd, NULL, NULL);
        if (client_fd < 0) continue;

        sessions[session_idx % MAX_CONNECTIONS].client_fd = client_fd;
        handle_client(client_fd, session_idx % MAX_CONNECTIONS);
        close(client_fd);
        session_idx++;
    }

    return 0;
}
